<script>
  // Draw the SVG chart
  const container = document.getElementById('chart-container');
  const width = container.clientWidth;
  const height = container.clientHeight;

  const margin = { top: 80, right: 60, bottom: 90, left: 120 };
  const innerWidth = width - margin.left - margin.right;
  const innerHeight = height - margin.top - margin.bottom;

  // Data approximations based on the study findings
  const data = [
    { year: 1700, temp: 0.02 }, { year: 1710, temp: -0.05 }, { year: 1720, temp: 0.08 },
    { year: 1730, temp: -0.03 }, { year: 1740, temp: 0.05 }, { year: 1750, temp: -0.08 },
    { year: 1760, temp: 0.04 }, { year: 1770, temp: -0.02 }, { year: 1780, temp: 0.06 },
    { year: 1790, temp: 0.1 }, { year: 1800, temp: 0.18 }, { year: 1810, temp: 0.25 },
    { year: 1820, temp: 0.28 }, { year: 1830, temp: 0.35 }, { year: 1840, temp: 0.42 },
    { year: 1850, temp: 0.48 }, { year: 1860, temp: 0.45 }, { year: 1870, temp: 0.52 },
    { year: 1880, temp: 0.50 }, { year: 1890, temp: 0.55 }, { year: 1900, temp: 0.58 },
    { year: 1910, temp: 0.62 }, { year: 1920, temp: 0.65 }, { year: 1930, temp: 0.70 },
    { year: 1940, temp: 0.75 }, { year: 1950, temp: 0.72 }, { year: 1960, temp: 0.80 },
    { year: 1970, temp: 0.88 }, { year: 1980, temp: 1.05 }, { year: 1990, temp: 1.25 },
    { year: 2000, temp: 1.38 }, { year: 2010, temp: 1.55 }, { year: 2020, temp: 1.72 }
  ];

  const minYear = 1700, maxYear = 2020;
  const minTemp = -0.2, maxTemp = 2.0;

  function xScale(year) {
    return margin.left + ((year - minYear) / (maxYear - minYear)) * innerWidth;
  }
  function yScale(temp) {
    return margin.top + innerHeight - ((temp - minTemp) / (maxTemp - minTemp)) * innerHeight;
  }

  // Smooth line generator (Catmull-Rom like)
  function getPathData(points) {
    let d = `M ${xScale(points[0].year)} ${yScale(points[0].temp)}`;
    for (let i = 1; i < points.length - 2; i++) {
      const xc = (xScale(points[i].year) + xScale(points[i + 1].year)) / 2;
      const yc = (yScale(points[i].temp) + yScale(points[i + 1].temp)) / 2;
      d += ` Q ${xScale(points[i].year)} ${yScale(points[i].temp)}, ${xc} ${yc}`;
    }
    d += ` T ${xScale(points[points.length-1].year)} ${yScale(points[points.length-1].temp)}`;
    return d;
  }

  const pathData = getPathData(data);

  let svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}">`;

  // Defs for gradient
  svg += `<defs>
    <linearGradient id="temp-gradient" x1="0" y1="1" x2="0" y2="0">
      <stop offset="0%" stop-color="#005b96" />
      <stop offset="30%" stop-color="#b3cde0" />
      <stop offset="50%" stop-color="#f4b41a" />
      <stop offset="80%" stop-color="#d9534f" />
      <stop offset="100%" stop-color="#a31915" />
    </linearGradient>
  </defs>`;

  // Y-axis grid & labels
  const yTicks = [-0.0, 0.5, 1.0, 1.5, 2.0];
  yTicks.forEach(t => {
    const y = yScale(t);
    const isThreshold = t === 1.5;
    if (isThreshold) {
      svg += `<line x1="${margin.left}" y1="${y}" x2="${width - margin.right}" y2="${y}" class="threshold-line" />`;
      // Threshold background box
      svg += `<rect x="${margin.left - 100}" y="${y - 25}" width="90" height="50" class="annotation-box" />`;
      svg += `<text x="${margin.left - 55}" y="${y + 12}" class="axis-text" font-weight="bold" fill="#a31915" text-anchor="middle">1.5°C</text>`;
      svg += `<text x="${width - margin.right + 20}" y="${y + 12}" class="annotation-text">Exceeded!</text>`;
    } else {
      svg += `<line x1="${margin.left}" y1="${y}" x2="${width - margin.right}" y2="${y}" class="grid-line" />`;
      svg += `<text x="${margin.left - 20}" y="${y + 12}" class="axis-text" text-anchor="end">${t.toFixed(1)}°C</text>`;
    }
  });

  // Additional Y-axis line for 0 baseline
  const yZero = yScale(0);
  svg += `<line x1="${margin.left}" y1="${yZero}" x2="${width - margin.right}" y2="${yZero}" class="grid-line-thick" />`;
  svg += `<text x="${width - margin.right - 250}" y="${yZero - 15}" class="axis-text" fill="#666">True Pre-Industrial Baseline (1700-1790)</text>`;

  // X-axis grid & labels
  const xTicks = [1700, 1750, 1800, 1850, 1900, 1950, 2000, 2020];
  xTicks.forEach(t => {
    const x = xScale(t);
    svg += `<line x1="${x}" y1="${margin.top}" x2="${x}" y2="${height - margin.bottom}" class="grid-line" />`;
    svg += `<text x="${x}" y="${height - margin.bottom + 50}" class="axis-text" text-anchor="middle">${t}</text>`;
  });

  // Highlight area for IPCC Baseline (1850-1900)
  const x1850 = xScale(1850);
  const x1900 = xScale(1900);
  svg += `<rect x="${x1850}" y="${margin.top}" width="${x1900 - x1850}" height="${innerHeight}" fill="#005b96" opacity="0.1" />`;
  svg += `<text x="${x1850 + (x1900-x1850)/2}" y="${margin.top + 50}" class="axis-text" fill="#005b96" text-anchor="middle" font-size="28px">IPCC</text>`;
  svg += `<text x="${x1850 + (x1900-x1850)/2}" y="${margin.top + 85}" class="axis-text" fill="#005b96" text-anchor="middle" font-size="28px">Baseline</text>`;

  // Draw data line
  svg += `<path d="${pathData}" class="data-line" />`;

  // Crossing point dot (interpolate around 1.5C crossing which is roughly 2008 in this generated data)
  // Let's just find the first point >= 1.5
  let crossX = xScale(2007);
  let crossY = yScale(1.5);
  svg += `<circle cx="${crossX}" cy="${crossY}" r="16" class="crossing-point" />`;

  // Line indicating hidden warming at 1850
  const y1850 = yScale(0.48);
  svg += `<line x1="${x1850}" y1="${yZero}" x2="${x1850}" y2="${y1850}" stroke="#a31915" stroke-width="6" stroke-dasharray="8 8" />`;
  svg += `<text x="${x1850 - 15}" y="${yZero - (yZero - y1850)/2 + 10}" class="axis-text" fill="#a31915" text-anchor="end" font-weight="bold">~0.5°C Hidden Warming</text>`;

  // Axes lines
  svg += `<line x1="${margin.left}" y1="${height - margin.bottom}" x2="${width - margin.right}" y2="${height - margin.bottom}" class="axis-line" />`;
  svg += `<line x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${height - margin.bottom}" class="axis-line" />`;

  // Axis Titles
  svg += `<text x="${margin.left + innerWidth/2}" y="${height - 15}" class="axis-title">Year</text>`;
  svg += `<text x="-${margin.top + innerHeight/2}" y="${45}" class="axis-title" transform="rotate(-90)">Temperature Anomaly (°C)</text>`;

  svg += `</svg>`;
  container.innerHTML = svg;
</script>

</body>
</html>
"""

